// DecodeBase64 decodes a base64-encoded string, automatically detecting the encoding variant.
// Tries the following encodings in order: RawURLEncoding, RawStdEncoding, URLEncoding, StdEncoding.
// Returns the decoded bytes on the first successful decode, or an error if all variants fail.
func DecodeBase64(input string) ([]byte, error) {
	// Try RawURLEncoding first
	if key, err := libBase64.RawURLEncoding.DecodeString(input); err == nil {
		return key, nil
	}

	// Try RawStdEncoding
	if key, err := libBase64.RawStdEncoding.DecodeString(input); err == nil {
		return key, nil
	}

	// Try URLEncoding
	if key, err := libBase64.URLEncoding.DecodeString(input); err == nil {
		return key, nil
	}

	// Try StdEncoding
	if key, err := libBase64.StdEncoding.DecodeString(input); err == nil {
		return key, nil
	}

	return nil, protoerrors.NewErrMissingInvalidData(nil, "failed to decode base64 string")
}

// GrpcStatusToHTTP maps a gRPC status error to an HTTP status code.
func GrpcStatusToHTTP(err error) int {
	if err == nil {
		return http.StatusOK
	}
	st, ok := status.FromError(err)
	if !ok {
		return http.StatusInternalServerError
	}
	switch st.Code() {
	case codes.OK:
		return http.StatusOK
	case codes.InvalidArgument:
		return http.StatusBadRequest
	case codes.Unauthenticated:
		return http.StatusUnauthorized
	case codes.PermissionDenied:
		return http.StatusForbidden
	case codes.NotFound:
		return http.StatusNotFound
	case codes.AlreadyExists:
		return http.StatusConflict
	case codes.ResourceExhausted:
		return http.StatusTooManyRequests
	case codes.FailedPrecondition:
		return http.StatusBadRequest
	case codes.Unimplemented:
		return http.StatusNotImplemented
	case codes.Unavailable:
		return http.StatusServiceUnavailable
	case codes.DeadlineExceeded:
		return http.StatusGatewayTimeout
	default:
		return http.StatusInternalServerError
	}
}
